  "inlineSchema": "// Provider console — the VENDOR's own database.\n//\n// This is not a clinic's database and must never become one. It holds the\n// registry of clinics sold to, their plans, their deal terms and their\n// deployment metadata. It holds no patient data of any kind.\n//\n// The hard rule, encoded below: **no clinic database credential is ever\n// stored here.** Provisioning needs one, but it is fetched from Neon at the\n// moment of use and discarded. What is stored is `neonProjectId` — a\n// reference, useless on its own. A breach of this console is therefore one\n// API key to rotate, not every clinic's PHI at once, which under the DPDP\n// Act is the difference between an incident and a catastrophe.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  // Own output path, same reasoning as clinic-api: three schemas in this\n  // monorepo would otherwise fight over the hoisted @prisma/client.\n  output   = \"../src/generated/prisma-client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n/// Who can sign in to the console. This is the vendor's own team.\nmodel ProviderUser {\n  id           String       @id @default(cuid())\n  email        String       @unique\n  passwordHash String\n  name         String\n  role         ProviderRole @default(OWNER)\n  isActive     Boolean      @default(true)\n  createdAt    DateTime     @default(now())\n\n  activity ActivityLog[]\n}\n\nenum ProviderRole {\n  OWNER\n  STAFF\n}\n\nenum AccountStatus {\n  LEAD // in conversation, nothing built\n  ONBOARDING // provisioning in progress\n  LIVE // serving patients\n  SUSPENDED // non-payment or at the clinic's request\n  CHURNED\n}\n\nenum PlanTier {\n  BASIC\n  STANDARD\n  PREMIUM\n  ENTERPRISE\n}\n\nenum BillingCycle {\n  MONTHLY\n  QUARTERLY\n  ANNUAL\n}\n\n/// One clinic customer.\nmodel ClinicAccount {\n  id   String @id @default(cuid())\n  /// URL-safe identifier used for generated subdomains and project names.\n  slug String @unique\n  name String\n\n  // Who to call when something breaks.\n  contactName  String?\n  contactEmail String?\n  contactPhone String?\n  city         String?\n  notes        String?\n\n  status AccountStatus @default(LEAD)\n  plan   PlanTier      @default(BASIC)\n\n  /// Features granted beyond the plan, for a deal that includes something\n  /// off-tier. Merged over the plan's defaults when the .env is generated,\n  /// so a one-off promise made in a sales call survives as configuration\n  /// rather than as a note nobody reads.\n  featureOverrides Json?\n\n  // ── Deal terms ────────────────────────────────────────────────────────\n  monthlyFee   Decimal?     @db.Decimal(10, 2)\n  currency     String       @default(\"INR\")\n  billingCycle BillingCycle @default(MONTHLY)\n  startedAt    DateTime?\n  renewsAt     DateTime?\n\n  // ── Deployment ────────────────────────────────────────────────────────\n  publicDomain String? // drasif.in\n  portalDomain String? // dashboard.drasif.in\n  apiDomain    String? // api.drasif.in\n\n  /// Neon project reference. NOT a credential — the connection string is\n  /// fetched from Neon at the moment it is needed and never written here.\n  neonProjectId      String?\n  /// Vercel project ids, so a redeploy can find them again.\n  vercelWebProjectId String?\n  vercelApiProjectId String?\n\n  /// True once the provisioning run has completed end to end.\n  provisionedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  steps    OnboardingStep[]\n  activity ActivityLog[]\n  health   HealthCheck[]\n\n  @@index([status])\n}\n\n/// The onboarding checklist for one clinic. Rows are created from a fixed\n/// template when the account is created, so progress is visible rather than\n/// living in someone's head.\nmodel OnboardingStep {\n  id        String        @id @default(cuid())\n  accountId String\n  account   ClinicAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)\n\n  key       String\n  label     String\n  /// Whether the console performs this step or a human does. Shown in the\n  /// UI so nobody waits on a button that was never going to exist.\n  automated Boolean @default(false)\n  sortOrder Int     @default(0)\n\n  done   Boolean   @default(false)\n  doneAt DateTime?\n  notes  String?\n\n  @@unique([accountId, key])\n  @@index([accountId, sortOrder])\n}\n\n/// Append-only record of what was done to an account and by whom. The same\n/// reasoning as the clinic's own audit log: an action on a customer's\n/// infrastructure should be attributable months later.\nmodel ActivityLog {\n  id        String         @id @default(cuid())\n  accountId String?\n  account   ClinicAccount? @relation(fields: [accountId], references: [id], onDelete: SetNull)\n\n  actorId   String?\n  actor     ProviderUser? @relation(fields: [actorId], references: [id], onDelete: SetNull)\n  /// Denormalized so the entry still reads after a team member leaves.\n  actorName String\n\n  action  String\n  detail  String?\n  /// False when the action ran in dry-run mode, so a rehearsal is never\n  /// mistaken for the real thing when reading the history back.\n  applied Boolean @default(true)\n\n  at DateTime @default(now())\n\n  @@index([accountId, at])\n  @@index([at])\n}\n\n/// Result of pinging a clinic's /health endpoint. Deliberately the only\n/// thing this console ever reads from a live clinic deployment — no patient\n/// data, no counts, nothing behind auth.\nmodel HealthCheck {\n  id        String        @id @default(cuid())\n  accountId String\n  account   ClinicAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)\n\n  ok         Boolean\n  statusCode Int?\n  latencyMs  Int?\n  error      String?\n  checkedAt  DateTime @default(now())\n\n  @@index([accountId, checkedAt])\n}\n",
